mapper.select:
select r.*, u.name as reporterName, u.avatar as reporterAvatar from report r left join user u on r.user_id = u.id
and r.status = #{status} and r.module = #{module}
order by r.id desc

mapper.update:
update report
status = #{status}, handle_result = #{handleResult}, handler_id = #{handlerId}, handle_time = #{handleTime},
where id = #{id}
